// Generated guardian art — TRY-OUT (Nov 22, 2026, Derek: "Ok can we try the generated ones?").
// The 18 generated guardians are flat PNGs and CANNOT be pushed to GitHub
// with push-files (it rejects binaries), so only the 3 finished composites
// (guardian cut out onto its detailed background) are embedded here, as
// small 900px WebP data URIs. Total ~175 KB, base64 ~234 KB. The other
// 15 combos do not exist as generated art yet and fall back to the SVG
// GuardianAvatar, which stays in the code as the fallback and the default.
// To go beyond 3 combos, the PNGs need a real host: an R2 bucket
// (active-life-quest-videos, Derek must create it in the Cloudflare
// dashboard — the API returns 403) or a wrangler deploy (needs
// `wrangler login`, interactive OAuth, not available here).
// Skin is baked into these pictures: the skin picker does nothing for
// the generated style, so Armor/Onboarding hide it while it is on.

import type { GuardianState } from './store';

const GUARDIAN_WEBP = 'data:image/webp;base64,';

const RANGER_WEBP = 'data:image/webp;base64,';

const SPELLWEAVER_WEBP = 'data:image/webp;base64,';

// The 3 combos with finished generated art. Key: classId/look/hair.
export const GENERATED_COMBOS: { classId: GuardianState['classId']; look: 'Female' | 'Male'; hair: string; label: string; src: string }[] = [
  { classId: 'Guardian', look: 'Male', hair: 'Short', label: 'Guardian · Male · Short', src: GUARDIAN_WEBP },
  { classId: 'Ranger', look: 'Female', hair: 'Long', label: 'Ranger · Female · Long', src: RANGER_WEBP },
  { classId: 'Spellweaver', look: 'Female', hair: 'Braided', label: 'Spellweaver · Female · Braided', src: SPELLWEAVER_WEBP },
];

export function generatedImageFor(g: GuardianState | null | undefined): string | null {
  if (!g) return null;
  const hit = GENERATED_COMBOS.find((c) => c.classId === g.classId && c.look === g.look && c.hair === g.hair);
  return hit ? hit.src : null;
}

export function generatedLabelFor(g: GuardianState | null | undefined): string | null {
  if (!g) return null;
  const hit = GENERATED_COMBOS.find((c) => c.classId === g.classId && c.look === g.look && c.hair === g.hair);
  return hit ? hit.label : null;
}